 var tree=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Locations/Decoration/Hilly_Prop_Tree_Oak_1.prefab"),root);tree.name="Supporting_Oak";tree.transform.localPosition=new Vector3(house.x,.2f,6);var rs=tree.GetComponentsInChildren<Renderer>();var bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);tree.transform.localScale*=18/bounds.size.y;bounds=rs[0].bounds;foreach(var r in rs)bounds.Encapsulate(r.bounds);tree.transform.position+=Vector3.up*(.2f-bounds.min.y);foreach(var c in tree.GetComponentsInChildren<Collider>())c.enabled=false;
 Deck(new Vector3(i==2?-3:0,4.8f,0),new Vector3(i==2?10:13,0,11));Box("Tree_Trunk_Support",new Vector3(house.x,2.4f,4.5f),new Vector3(1.2f,4.8f,1.2f),dark);
 Rail(new Vector3(i==2?-8:-6.5f,4.8f,-5.5f),new Vector3(i==2?-8:-6.5f,4.8f,5.5f));Rail(new Vector3(i==2?-8:-6.5f,4.8f,5.5f),new Vector3(i==2?2:6.5f,4.8f,5.5f));
