 else if(i==1){Steps(new Vector3(-9,.2f,-16),new Vector3(-9,2.5f,-10),2.8f);Deck(new Vector3(-7,2.5f,-9),new Vector3(7,0,3));Steps(new Vector3(-4,2.5f,-9),new Vector3(-4,4.8f,-3),2.8f);route=new[]{new Vector3(-9,.3f,-16.7f),new Vector3(-9,2.6f,-9),new Vector3(-4,2.6f,-9),new Vector3(-4,4.9f,-2.5f)};}
 else {Deck(new Vector3(7,3, -5),new Vector3(5,0,5));Steps(new Vector3(7,.2f,-15),new Vector3(7,3,-7.5f),2.8f);var ramp=Box("Bridge_Ramp",new Vector3(2,3.77f,-4),new Vector3(2.4f,.25f,Mathf.Sqrt(100+3.24f)),wood);ramp.transform.localRotation=Quaternion.LookRotation(new Vector3(-10,1.8f,0));Rail(new Vector3(7,3,-5.2f),new Vector3(-3,4.8f,-5.2f));route=new[]{new Vector3(7,.3f,-15.7f),new Vector3(7,3.1f,-5),new Vector3(7,3.1f,-4),new Vector3(-3,4.9f,-4)};}
